// Normalize post-call payload and detect handoff/complaint tokens.
const body = $input.first().json.body || {};
const extracted = (body.call_report && body.call_report.extracted_variables) || {};
const summary = String(body.summary || '');

const rawName = (extracted.customer_name || '').trim();
const BANNED_NAMES = ['anonymous','anon','n/a','na','none','test','ai','bot','siri','unknown','unnamed'];
const isPlaceholder = !rawName || BANNED_NAMES.includes(rawName.toLowerCase()) || rawName.length < 2;
const customerName = isPlaceholder ? 'MISSING' : rawName;

const rawPhone = String(body.caller_number || body.phone_number || extracted.phone_number || '').replace(/[^0-9]/g,'');
const phone = rawPhone.length >= 10 ? rawPhone.slice(-10) : 'MISSING';

const handoff = /^\s*HANDOFF[:\s]/i.test(summary);
const complaint = /^\s*COMPLAINT[:\s]/i.test(summary);
const needsAlert = handoff || complaint;

const status = complaint ? 'Priority Complaint' : (handoff ? 'Handoff Required' : 'Completed');

return [{ json: {
  customer_name: customerName,
  phone_number: phone,
  service_requested: (extracted.service_requested || 'N/A').trim(),
  preferred_date_time: (extracted.preferred_date_time || 'N/A').trim(),
  complaint_details: (extracted.complaint_details || '').trim(),
  language_detected: (extracted.language_detected || '').trim(),
  sentiment: (extracted.sentiment || '').trim(),
  handoff_reason: needsAlert ? (extracted.handoff_reason || summary.split(':').slice(1).join(':').trim() || 'unspecified') : '',
  duration: body.duration || '',
  summary: summary,
  status,
  needs_alert: needsAlert,
  is_placeholder_name: isPlaceholder,
  call_id: body.id || body.call_id || '',
  agent_id: body.agent_id || '',
  channel: 'voice'
} }];

// Normalize text-chat alert payload.
const body = $input.first().json.body || {};
const phone = String(body.phone_number || body.caller_number || '').replace(/[^0-9]/g,'').slice(-10) || 'MISSING';
const reason = (body.reason || body.complaint || 'user requested manager').toString().trim();
const name = (body.customer_name || body.name || 'Chat user').toString().trim();
return [{ json: {
  customer_name: name,
  phone_number: phone,
  status: 'Handoff Required (Text)',
  handoff_reason: reason,
  language_detected: body.language || '',
  summary: `HANDOFF: text-chat requested manager. Reason: ${reason}`,
  needs_alert: true,
  channel: 'text'
} }];

// Compute free slots between 9 AM and 4:30 PM IST, in 60-min windows.
// Assumes calendar returns events in the same date window (IST 09:00-16:30 = UTC 03:30-11:00).
const master = ['09:00','10:00','10:30','11:00','12:00','13:00','14:00','15:00','16:00','16:30'];
const dateStr = $('Route Calendar Action').first().json.body.date;
const events = $input.all().map(x => x.json);

function toISTHM(iso){
  if(!iso) return null;
  const d = new Date(iso);
  const ist = new Date(d.getTime() + (330 - d.getTimezoneOffset()) * 60000);
  return ist.toISOString().slice(11,16);
}

const busy = events.map(ev => ({ start: toISTHM(ev.start?.dateTime || ev.start), end: toISTHM(ev.end?.dateTime || ev.end) })).filter(b => b.start && b.end);

function overlaps(slot, busy){
  const [sH,sM] = slot.split(':').map(Number);
  const slotStart = sH*60+sM;
  const slotEnd = slotStart + 60;
  return busy.some(b => {
    const [bsH,bsM] = b.start.split(':').map(Number);
    const [beH,beM] = b.end.split(':').map(Number);
    const bStart = bsH*60+bsM, bEnd = beH*60+beM;
    return slotStart < bEnd && slotEnd > bStart;
  });
}

const freeIST = master.filter(s => !overlaps(s, busy));
// Format for user output
const pretty = freeIST.map(s => {
  const [h,m] = s.split(':').map(Number);
  const per = h < 12 ? 'AM' : 'PM';
  const hh = h === 0 ? 12 : (h > 12 ? h - 12 : h);
  return `${hh}:${String(m).padStart(2,'0')} ${per}`;
});

return [{ json: { success: true, date: dateStr, free_slots: pretty, free_slots_24h: freeIST, bookable_range: '9:00 AM - 4:30 PM', message: pretty.length ? `Available slots on ${dateStr}: ${pretty.join(', ')}` : `No free slots on ${dateStr}. Suggest another date.` } }];

// Overlap guard + validation for book action.
const body = $('Route Calendar Action').first().json.body || {};
const events = $input.all().map(x => x.json);

const BANNED = ['anonymous','anon','n/a','na','none','test','ai','bot','siri','unknown','unnamed'];
const name = String(body.name || '').trim();
const phone = String(body.phone || body.phone_number || '').replace(/[^0-9]/g,'').slice(-10);
const dateStr = body.date;
const timeStr = String(body.time || '').slice(0,5); // HH:MM

// Validate
const errors = [];
if (!name || BANNED.includes(name.toLowerCase().split(/[\s(]/)[0]) || name.length < 2) errors.push('invalid_or_anonymous_name');
if (phone.length !== 10) errors.push('invalid_phone');
if (!dateStr || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) errors.push('invalid_date');
if (!timeStr || !/^\d{2}:\d{2}$/.test(timeStr)) errors.push('invalid_time');

// Bookable hours
const [th,tm] = timeStr.split(':').map(Number);
const minutes = th*60+tm;
if (minutes < 540 || minutes > 990) errors.push('slot_outside_bookable_hours'); // 9:00-16:30

if (errors.length){
  return [{ json: { success: false, action: 'book', errors, message: `Cannot book: ${errors.join(', ')}` } }];
}

// Overlap check
function toISTMin(iso){
  if(!iso) return null;
  const d = new Date(iso);
  const ist = new Date(d.getTime() + (330 - d.getTimezoneOffset()) * 60000);
  return ist.getUTCHours()*60 + ist.getUTCMinutes();
}
const reqStart = minutes;
const reqEnd = minutes + 60;
const busy = events.some(ev => {
  const bs = toISTMin(ev.start?.dateTime || ev.start);
  const be = toISTMin(ev.end?.dateTime || ev.end);
  if (bs == null || be == null) return false;
  return reqStart < be && reqEnd > bs;
});

if (busy){
  return [{ json: { success: false, action: 'book', errors: ['slot_taken'], message: 'Requested slot is already booked. Please suggest another slot.' } }];
}

return [{ json: {
  success: true, action: 'book', validated: true,
  name, phone, date: dateStr, time: timeStr,
  service_requested: body.service_requested || body.service || 'unspecified',
  language: body.language || ''
} }];

// Return the first upcoming event matching phone in description.
const body = $('Route Calendar Action').first().json.body || {};
const phone = String(body.phone || '').replace(/[^0-9]/g,'').slice(-10);
const events = $input.all().map(x => x.json).filter(ev => (ev.description || '').includes(phone));

if (!events.length){
  return [{ json: { success: false, action: 'lookup_by_phone', message: 'No booking found for this phone number.' } }];
}

events.sort((a,b) => new Date(a.start?.dateTime || a.start) - new Date(b.start?.dateTime || b.start));
const ev = events[0];
const startISO = ev.start?.dateTime || ev.start;
const ist = new Date(new Date(startISO).getTime() + (330 - new Date(startISO).getTimezoneOffset())*60000);
const dateStr = ist.toISOString().slice(0,10);
const timeStr = ist.toISOString().slice(11,16);

// Extract name and service from summary "Name (service)"
const m = (ev.summary || '').match(/^(.+?)\s*\((.+)\)/);
const name = m ? m[1].trim() : (ev.summary || '').trim();
const service = m ? m[2].trim() : 'unspecified';

return [{ json: {
  success: true,
  action: 'lookup_by_phone',
  event_id: ev.id,
  name,
  phone,
  date: dateStr,
  time: timeStr,
  service_requested: service,
  message: `Found booking for ${name} on ${dateStr} at ${timeStr} for ${service}.`
} }];

// Validate reschedule input and find the target event.
const body = $('Route Calendar Action').first().json.body || {};
const events = $input.all().map(x => x.json);
const phone = String(body.phone || '').replace(/[^0-9]/g,'').slice(-10);
const newDate = body.new_date;
const newTime = String(body.new_time || '').slice(0,5);

const errors = [];
if (phone.length !== 10) errors.push('invalid_phone');
if (!/^\d{4}-\d{2}-\d{2}$/.test(newDate || '')) errors.push('invalid_new_date');
if (!/^\d{2}:\d{2}$/.test(newTime)) errors.push('invalid_new_time');
const [th,tm] = (newTime || '00:00').split(':').map(Number);
if (th*60+tm < 540 || th*60+tm > 990) errors.push('new_slot_outside_bookable_hours');
if (errors.length) return [{ json: { success: false, action: 'reschedule', errors, message: `Cannot reschedule: ${errors.join(', ')}` } }];

const matched = events.filter(ev => (ev.description || '').includes(phone));
if (!matched.length) return [{ json: { success: false, action: 'reschedule', message: 'No existing booking found for this phone number.' } }];

matched.sort((a,b) => new Date(a.start?.dateTime || a.start) - new Date(b.start?.dateTime || b.start));
const ev = matched[0];
const nameMatch = (ev.summary || '').match(/^(.+?)\s*\((.+)\)/);
const name = nameMatch ? nameMatch[1].trim() : (ev.summary || '').trim();
const service = nameMatch ? nameMatch[2].trim() : 'unspecified';

return [{ json: {
  success: true, action: 'reschedule', validated: true,
  event_id: ev.id,
  name, phone, service_requested: service,
  old_start: ev.start?.dateTime || ev.start,
  new_date: newDate,
  new_time: newTime,
  language: body.language || ''
} }];

